"use client";

import {
  closestCorners,
  DndContext,
  type DragEndEvent,
  type DragMoveEvent,
  type DragOverEvent,
  DragOverlay,
  KeyboardCode,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
} from "@dnd-kit/core";
import { arrayMove, sortableKeyboardCoordinates } from "@dnd-kit/sortable";
import { motion, type MotionStyle, useReducedMotion, useSpring, useTransform } from "motion/react";
import { Fragment, useId, useRef, useState } from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { RollingText } from "../parts/rolling-text";
import { CardCell } from "./kanban-board/card-cell";
import { CardDetails } from "./kanban-board/card-details";
import { CardFace } from "./kanban-board/card-face";
import { type ColumnId, COLUMNS, columnName, KANBAN_CARDS, type KanbanCard, type LaneId, LANES } from "./kanban-board/data";

type View = "status" | "lanes";

const VIEWS: { value: View; label: string }[] = [
  { value: "status", label: "Status" },
  { value: "lanes", label: "Swimlanes" },
];

const isColumn = (id: string): id is ColumnId => COLUMNS.some((column) => column.id === id);
const isLane = (id: string): id is LaneId => LANES.some((lane) => lane.id === id);

/** Reads a drop area id back into a column and, in the lane view, a lane. */
function parseArea(id: string): { column: ColumnId; lane?: LaneId } | null {
  const [column, lane] = id.split(":");
  if (!column || !isColumn(column)) return null;
  return lane && isLane(lane) ? { column, lane } : { column };
}

/**
 * A kanban board with work-in-progress limits. Drag a card, or focus it and
 * press Space to lift it, the arrows to move it, and Space to drop it. Enter
 * opens a card. The lifted card tilts with its sideways speed, and the column
 * counts update as it crosses.
 */
export function KanbanBoard({ className }: { className?: string }) {
  const [cards, setCards] = useState(KANBAN_CARDS);
  const [view, setView] = useState<View>("status");
  const [activeId, setActiveId] = useState<string | null>(null);
  const [openId, setOpenId] = useState<string | null>(null);
  const before = useRef(cards);
  const lastMove = useRef({ x: 0, t: 0 });
  const reduceMotion = useReducedMotion();
  const tilt = useSpring(0, { stiffness: 260, damping: 22 });
  const tiltDeg = useTransform(tilt, (value) => `${value}deg`);
  const titleId = useId();
  const dndId = useId();

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 6 } }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
      keyboardCodes: { start: [KeyboardCode.Space], cancel: [KeyboardCode.Esc], end: [KeyboardCode.Space, KeyboardCode.Enter] },
    }),
  );

  const areaOf = (card: KanbanCard) => (view === "lanes" ? `${card.column}:${card.lane}` : card.column);
  const findArea = (id: string) => {
    const card = cards.find((item) => item.id === id);
    return card ? areaOf(card) : id;
  };
  const titleOf = (id: string | number) => cards.find((card) => card.id === id)?.title ?? "Card";
  const placeName = (id: string | number) => {
    const area = parseArea(findArea(String(id)));
    if (!area) return "the board";
    const lane = area.lane ? `, ${LANES.find((item) => item.id === area.lane)?.label}` : "";
    return `${columnName(area.column)}${lane}`;
  };

  // Crossing into another area moves the card there at once, so that area opens a slot and its count updates live.
  const onDragOver = ({ active, over }: DragOverEvent) => {
    if (!over) return;
    const from = findArea(String(active.id));
    const to = findArea(String(over.id));
    if (from === to) return;
    const area = parseArea(to);
    const moving = cards.find((card) => card.id === active.id);
    if (!area || !moving) return;
    const rest = cards.filter((card) => card.id !== active.id);
    const at = rest.findIndex((card) => card.id === over.id);
    rest.splice(at < 0 ? rest.length : at, 0, { ...moving, column: area.column, lane: area.lane ?? moving.lane });
    setCards(rest);
  };

  const onDragMove = ({ delta }: DragMoveEvent) => {
    if (reduceMotion) return;
    const now = performance.now();
    const dt = Math.max(16, now - lastMove.current.t);
    const speed = (delta.x - lastMove.current.x) / dt;
    lastMove.current = { x: delta.x, t: now };
    tilt.set(Math.max(-8, Math.min(8, speed * 6)));
  };

  const finish = () => {
    setActiveId(null);
    tilt.set(0);
  };

  const onDragEnd = ({ active, over }: DragEndEvent) => {
    finish();
    if (!over || active.id === over.id || findArea(String(active.id)) !== findArea(String(over.id))) return;
    const from = cards.findIndex((card) => card.id === active.id);
    const to = cards.findIndex((card) => card.id === over.id);
    if (from >= 0 && to >= 0) setCards(arrayMove(cards, from, to));
  };

  const add = (areaId: string, title: string) => {
    const area = parseArea(areaId);
    if (!area) return;
    const next = cards.length + 230;
    setCards((current) => [
      ...current,
      {
        id: `new-${Date.now()}`,
        ref: `FH-${next}`,
        title,
        label: "desk",
        column: area.column,
        lane: area.lane ?? "normal",
        due: "Nov 30",
        subtasksDone: 0,
        subtasks: 0,
        points: 1,
        assignee: "ines",
        detail: "Added from the board. No details yet.",
      },
    ]);
  };

  const active = cards.find((card) => card.id === activeId) ?? null;
  const areas = view === "lanes" ? LANES.map((lane) => lane.id) : [null];

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-4">
        <h2 id={titleId} className="flex items-baseline gap-2 text-base font-semibold">
          Clinic app board
          <span className="flex items-baseline gap-1 text-sm font-normal text-muted-foreground">
            <RollingText text={String(cards.length)} /> cards
          </span>
        </h2>
        <SegmentedControl aria-label="Group cards by" options={VIEWS} value={view} onValueChange={setView} />
      </header>

      <DndContext
        id={dndId}
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragStart={({ active: lifted }) => {
          before.current = cards;
          lastMove.current = { x: 0, t: performance.now() };
          setActiveId(String(lifted.id));
        }}
        onDragMove={onDragMove}
        onDragOver={onDragOver}
        onDragEnd={onDragEnd}
        onDragCancel={() => {
          finish();
          setCards(before.current);
        }}
        accessibility={{
          screenReaderInstructions: {
            draggable:
              "Press Enter to open the card. Press Space to lift it, the arrow keys to move it within a column or to the next column, and Space again to drop it. Escape puts it back.",
          },
          announcements: {
            onDragStart: ({ active: lifted }) => `Lifted ${titleOf(lifted.id)}.`,
            onDragOver: ({ active: lifted, over }) => (over ? `${titleOf(lifted.id)} is in ${placeName(over.id)}.` : undefined),
            onDragEnd: ({ active: lifted, over }) => `${titleOf(lifted.id)} dropped in ${over ? placeName(over.id) : "its place"}.`,
            onDragCancel: ({ active: lifted }) => `Move cancelled. ${titleOf(lifted.id)} is back where it was.`,
          },
        }}
      >
        {/* Relative, so the hidden labels inside the columns stay in this scroll box instead of widening the page. */}
        <div className="scroll-fade-effect-x scrollbar-none relative overflow-x-auto">
          <div className="grid min-w-224 grid-cols-4 gap-x-3 gap-y-2 p-4">
            {COLUMNS.map((column) => {
              const count = cards.filter((card) => card.column === column.id).length;
              const over = column.limit > 0 && count > column.limit;
              return (
                <h3 key={column.id} className="flex items-center justify-between gap-2 px-1 text-sm font-medium">
                  {column.label}
                  <span
                    className={cn(
                      "rounded-full border px-1.5 text-xs tabular-nums",
                      over ? "border-marketing-orange-ink text-marketing-orange-ink" : "border-border text-muted-foreground",
                    )}
                  >
                    {column.limit > 0 ? `${count} of ${column.limit}` : count}
                    {over ? <span className="sr-only">, over the limit</span> : null}
                  </span>
                </h3>
              );
            })}
            {areas.map((lane) => (
              <Fragment key={lane ?? "all"}>
                {lane ? (
                  <p className="col-span-4 mt-2 border-t border-border px-1 pt-3 text-xs font-medium text-muted-foreground">
                    {LANES.find((item) => item.id === lane)?.label}
                  </p>
                ) : null}
                {COLUMNS.map((column) => {
                  const id = lane ? `${column.id}:${lane}` : column.id;
                  return (
                    <CardCell
                      key={id}
                      id={id}
                      name={lane ? `${column.label}, ${LANES.find((item) => item.id === lane)?.label}` : column.label}
                      cards={cards.filter((card) => areaOf(card) === id)}
                      onOpen={setOpenId}
                      onAdd={(title) => add(id, title)}
                    />
                  );
                })}
              </Fragment>
            ))}
          </div>
        </div>
        <DragOverlay>
          {active ? (
            <motion.div
              style={
                // SAFETY: the only key is a CSS custom property, which motion animates but MotionStyle does not list.
                { "--tilt": tiltDeg } as MotionStyle
              }
              className="rotate-(--tilt)"
              initial={reduceMotion ? false : { scale: 1 }} animate={{ scale: reduceMotion ? 1 : 1.03 }}>
              <CardFace card={active} lifted />
            </motion.div>
          ) : null}
        </DragOverlay>
      </DndContext>

      <CardDetails card={cards.find((card) => card.id === openId) ?? null} onClose={() => setOpenId(null)} />
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

"use client";

import { useDroppable } from "@dnd-kit/core";
import { SortableContext, verticalListSortingStrategy } from "@dnd-kit/sortable";
import { type FormEvent, useState } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

import { PlusIcon } from "../../parts/icons";
import type { KanbanCard } from "./data";
import { SortableCard } from "./sortable-card";

/** Props for one drop area: a whole column, or one lane of a column. */
export interface CardCellProps {
  /** The drop area's id, which the board reads back to place a card. */
  id: string;
  /** Names the area for the add field, such as "Doing". */
  name: string;
  cards: KanbanCard[];
  onOpen: (id: string) => void;
  onAdd: (title: string) => void;
}

/**
 * A list of sortable cards that also takes a dropped card when empty, with an
 * add-card row at its foot.
 */
export function CardCell({ id, name, cards, onOpen, onAdd }: CardCellProps) {
  const { setNodeRef, isOver } = useDroppable({ id });
  const [adding, setAdding] = useState(false);
  const [draft, setDraft] = useState("");

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!draft.trim()) return;
    onAdd(draft.trim());
    setDraft("");
  };

  return (
    <div className="flex min-w-0 flex-col gap-2">
      <SortableContext id={id} items={cards.map((card) => card.id)} strategy={verticalListSortingStrategy}>
        <ul
          ref={setNodeRef}
          className={cn(
            "flex min-h-14 flex-col gap-2 rounded-xl border border-dashed p-1 motion-safe:transition-colors",
            isOver ? "border-chart-1" : cards.length === 0 ? "border-border" : "border-transparent",
          )}
        >
          {cards.map((card) => (
            <SortableCard key={card.id} card={card} onOpen={onOpen} />
          ))}
        </ul>
      </SortableContext>
      {adding ? (
        <form onSubmit={submit} className="flex flex-col gap-2 px-1">
          <Input
            autoFocus
            aria-label={`New card in ${name}`}
            placeholder="Card title"
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === "Escape") setAdding(false);
            }}
          />
          <div className="flex justify-end gap-2">
            <Button type="button" variant="ghost" size="sm" onClick={() => setAdding(false)}>
              Close
            </Button>
            <Button type="submit" size="sm" disabled={!draft.trim()}>
              Add card
            </Button>
          </div>
        </form>
      ) : (
        <Button variant="ghost" size="sm" className="justify-start" onClick={() => setAdding(true)}>
          <PlusIcon />
          Add card<span className="sr-only"> to {name}</span>
        </Button>
      )}
    </div>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

/** A warning triangle, from the chosen icon pack. */
export const AlertTriangleIcon = packIcon("alert-triangle");
/** An arrow that points down, from the chosen icon pack. */
