/** A check mark, from the chosen icon pack. */
export const CheckIcon = packIcon("check");
/** A chevron that points down, from the chosen icon pack. */
export const ChevronDownIcon = packIcon("chevron-down");
/** A chevron that points right, from the chosen icon pack. */
export const ChevronRightIcon = packIcon("chevron-right");
/** A check mark in a circle, from the chosen icon pack. */
export const CircleCheckIcon = packIcon("circle-check");
/** A cross in a circle, from the chosen icon pack. */
export const CircleXIcon = packIcon("circle-x");
/** A download arrow, from the chosen icon pack. */
export const DownloadIcon = packIcon("download");
/** A globe, from the chosen icon pack. */
export const GlobeIcon = packIcon("globe");
/** An expand mark, from the chosen icon pack. */
export const MaximizeIcon = packIcon("expand");
/** A speech bubble, from the chosen icon pack. */
export const MessageIcon = packIcon("message");
/** A play mark, from the chosen icon pack. */
export const PlayerPlayFilledIcon = packIcon("play");
/** A plus, from the chosen icon pack. */
export const PlusIcon = packIcon("plus");
/** A refresh mark, from the chosen icon pack. */
export const RefreshIcon = packIcon("refresh");
/** Sparkles, from the chosen icon pack. */
export const SparklesIcon = packIcon("sparkles");
/** Two people, from the chosen icon pack. */
export const UsersIcon = packIcon("users");
/** A close mark, from the chosen icon pack. */
export const XIcon = packIcon("x");

/** Two arrows that cross, for swapping two things. */
export const ArrowsShuffleIcon = ownIcon(
  <>
    <path d="M2 4.5h2.2c1.2 0 2.3.6 3 1.6l1.6 3.8c.7 1 1.8 1.6 3 1.6H14" />
    <path d="M2 11.5h2.2c1 0 1.9-.4 2.6-1.1M9.2 5.6c.7-.7 1.6-1.1 2.6-1.1H14" />
    <path d="M12 2.5l2 2-2 2M12 9.5l2 2-2 2" />
  </>,
);

/** Six dots, for a handle a person drags. */
export const GripVerticalIcon = ownIcon(
  <path d="M6 3.5h.01M10 3.5h.01M6 8h.01M10 8h.01M6 12.5h.01M10 12.5h.01" strokeWidth="2" />,
);

/** Two bars, for pause. */
export const PlayerPauseFilledIcon = ownIcon(<path d="M5.5 3.5v9M10.5 3.5v9" strokeWidth="2.5" />);

/** A bin, for remove. */
export const TrashIcon = ownIcon(
  <>
    <path d="M2.5 4.5h11M6 4.5V3a.5.5 0 0 1 .5-.5h3A.5.5 0 0 1 10 3v1.5" />
    <path d="M4 4.5l.6 8a1 1 0 0 0 1 .9h4.8a1 1 0 0 0 1-.9l.6-8M6.75 7v4M9.25 7v4" />
  </>,
);

import type { Hue } from "../shared/people";

/** The board's columns, each with a work-in-progress limit. A limit of 0 means none. */
export const COLUMNS = [
  { id: "todo", label: "To do", limit: 0 },
  { id: "doing", label: "Doing", limit: 3 },
  { id: "check", label: "Checking", limit: 2 },
  { id: "shipped", label: "Shipped", limit: 0 },
] as const;

/** One column id. */
export type ColumnId = (typeof COLUMNS)[number]["id"];

/** The two swimlanes, by urgency. */
export const LANES = [
  { id: "urgent", label: "Urgent" },
  { id: "normal", label: "Everything else" },
] as const;

/** One lane id. */
export type LaneId = (typeof LANES)[number]["id"];

/** The labels a card can carry, each with its hue. */
export const LABELS = {
  patients: { label: "Patient app", hue: 1 },
  desk: { label: "Front desk", hue: 3 },
  rooms: { label: "Rooms", hue: 4 },
  data: { label: "Reports", hue: 5 },
} satisfies Record<string, { label: string; hue: Hue }>;

/** One label id. */
export type LabelId = keyof typeof LABELS;

/** One card on the board. */
export interface KanbanCard {
  id: string;
  /** The short reference shown on the card, such as FH-214. */
  ref: string;
  title: string;
  label: LabelId;
  column: ColumnId;
  lane: LaneId;
  due: string;
  subtasksDone: number;
  subtasks: number;
  points: number;
  assignee: string;
  detail: string;
}

/** The sample board, in display order. */
export const KANBAN_CARDS: KanbanCard[] = [
  { id: "k1", ref: "FH-214", title: "Patients can cancel from the reminder text", label: "patients", column: "todo", lane: "urgent", due: "Nov 18", subtasksDone: 0, subtasks: 4, points: 3, assignee: "noor", detail: "A reply of C cancels the visit and frees the slot for the waitlist." },
  { id: "k2", ref: "FH-219", title: "Print the day sheet for each room", label: "rooms", column: "todo", lane: "normal", due: "Nov 24", subtasksDone: 0, subtasks: 2, points: 2, assignee: "kofi", detail: "One page per room, with each visit and the practitioner's name." },
  { id: "k3", ref: "FH-221", title: "Weekly no-show report by clinic", label: "data", column: "todo", lane: "normal", due: "Nov 27", subtasksDone: 1, subtasks: 3, points: 3, assignee: "arjun", detail: "Sent to clinic managers every Monday at 8 am." },
  { id: "k4", ref: "FH-203", title: "Check in a patient with their date of birth", label: "desk", column: "doing", lane: "urgent", due: "Nov 13", subtasksDone: 2, subtasks: 3, points: 2, assignee: "ines", detail: "The front desk types the date of birth and the visit opens." },
  { id: "k5", ref: "FH-207", title: "Block a room for cleaning between visits", label: "rooms", column: "doing", lane: "normal", due: "Nov 16", subtasksDone: 1, subtasks: 4, points: 5, assignee: "tomas", detail: "Ten minutes by default, set per room type." },
  { id: "k6", ref: "FH-198", title: "Show the next free slot on the clinic page", label: "patients", column: "check", lane: "normal", due: "Nov 12", subtasksDone: 3, subtasks: 3, points: 3, assignee: "lena", detail: "Reads the first slot open to new patients across practitioners." },
  { id: "k7", ref: "FH-190", title: "Export visits as a spreadsheet", label: "data", column: "shipped", lane: "normal", due: "Nov 6", subtasksDone: 2, subtasks: 2, points: 2, assignee: "arjun", detail: "Date range, clinic and practitioner filters carry over to the file." },
  { id: "k8", ref: "FH-187", title: "Waitlist offers a slot by text", label: "patients", column: "shipped", lane: "urgent", due: "Nov 4", subtasksDone: 4, subtasks: 4, points: 5, assignee: "noor", detail: "The first patient to reply yes gets the slot." },
];

/** The name of a column. */
export const columnName = (id: ColumnId) => COLUMNS.find((column) => column.id === id)?.label ?? id;

/** The five chart hues, in order. A person or a calendar takes one by index. */
export type Hue = 1 | 2 | 3 | 4 | 5;

/** One member of the Fernhill team, used across the project blocks. */
export interface Person {
  id: string;
  name: string;
  initials: string;
  hue: Hue;
}

/** The Fernhill team. Every block draws its owners, attendees and authors from this list. */
export const TEAM: Person[] = [
  { id: "ines", name: "Ines Varga", initials: "IV", hue: 1 },
  { id: "tomas", name: "Tomas Reyes", initials: "TR", hue: 2 },
  { id: "noor", name: "Noor Haddad", initials: "NH", hue: 3 },
  { id: "kofi", name: "Kofi Mensah", initials: "KM", hue: 4 },
