/** Props for a card a person can drag, open or move with the keyboard. */
export interface SortableCardProps {
  card: KanbanCard;
  onOpen: (id: string) => void;
}

/**
 * One draggable card. Its slot stays in the column as a faint outline while
 * the lifted copy rides the pointer, and neighbours glide aside as the slot
 * moves. Enter opens the card; Space lifts it.
 */
export function SortableCard({ card, onOpen }: SortableCardProps) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: card.id });
  return (
    <li
      ref={setNodeRef}
      style={
        // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
        { "--drag-shift": CSS.Translate.toString(transform) ?? "none" } as VarStyle
      }
      className={cn("list-none transform-(--drag-shift)", transition && "motion-safe:transition-transform motion-safe:duration-200")}
    >
      <div
        {...attributes}
        {...listeners}
        aria-roledescription="card"
        aria-label={`${card.ref}, ${card.title}, in ${columnName(card.column)}, due ${card.due}`}
        aria-haspopup="dialog"
        onClick={() => onOpen(card.id)}
        onKeyDown={(event) => {
          listeners?.onKeyDown?.(event);
          if (event.key === "Enter" && !isDragging) onOpen(card.id);
        }}
        className={cn(
          "cursor-grab touch-manipulation rounded-xl outline-none focus-visible:ring-2 focus-visible:ring-ring active:cursor-grabbing",
          isDragging && "opacity-40",
        )}
      >
        <CardFace card={card} />
      </div>
    </li>
  );
}

